using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using EmulatorHub;
class NavigationTiming {
 static void Pump(int ms){var watch=Stopwatch.StartNew();while(watch.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(2);}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);var data=Store.Load();NextData.Ensure(data);LibraryAdditions.Ensure(data);ExperienceData.Ensure(data);data.Games=new List<GameEntry>();data.Emulators=new List<EmulatorProfile>();data.Collections=new List<GameCollection>();data.SaveReviews.Clear();data.Theme.EnableMotion=false;data.Theme.UiScalePercent=100;data.Enhancements.TextPercent=100;File.WriteAllText("fixture.rom","fixture");for(int i=0;i<1000;i++)data.Games.Add(new GameEntry{Id="timing"+i,Title="Fixture "+i.ToString("0000"),Path=Path.GetFullPath("fixture.rom"),Tags=new List<string>(),Favorite=i<8,Pinned=i<8});Store.Save(data);using(var form=new MainForm(true)){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-3000,-3000);form.Show();Pump(100);var tabs=(TabControl)typeof(MainForm).GetField("workspaceNavigation",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);var times=new List<double>();for(int i=0;i<18;i++){var watch=Stopwatch.StartNew();tabs.SelectedIndex=(i+1)%3;Application.DoEvents();watch.Stop();times.Add(watch.Elapsed.TotalMilliseconds);Pump(30);}Console.WriteLine("Version "+typeof(MainForm).Assembly.GetName().Version+"; 1000 games; 18 navigation changes: total="+times.Sum().ToString("F0")+" ms; median="+times.OrderBy(x=>x).ElementAt(times.Count/2).ToString("F0")+" ms; max="+times.Max().ToString("F0")+" ms");var open=Stopwatch.StartNew();for(int i=0;i<10;i++)using(var dialog=new StartupAssistantDialog()){dialog.ShowInTaskbar=false;dialog.StartPosition=FormStartPosition.Manual;dialog.Location=new Point(-3000,-3000);dialog.Show();Application.DoEvents();dialog.Close();}Console.WriteLine("10 startup dialog construction/show/close cycles: "+open.ElapsedMilliseconds+" ms");form.Close();}}
}
